  "returned": 1,
  "items": [
    {
      "method": "POST",
      "path": "/revit/export-visible-elements",
      "title": "Export Visible Elements",
      "description": "Export a mapped view image plus visible-element inventory on the same raster-consistent coordinate basis. Returns element ids, category/type/source/host context, explicit hostingSurface + link-host metadata, orientation payloads (facing/hand/basis/rotation), bbox/location geometry, image-space coordinates, visibleText for TextNotes/tags, and taggedSpatial for room/space tags in supported 2D views. Linked annotation tags use their transformed tag-head positions for frame inclusion, mapping, and geometry when a model bounding box is unavailable. Optional modelBounds:[minX,minY,minZ,maxX,maxY,maxZ] restricts host and transformed linked elements to an intersecting host-model box before the safety limit is applied. limit is 1..2000; page, filter categories, or use modelBounds instead of requesting a larger inventory. Body: {viewId?,imageSize?,includeMapping?,categories?,excludeCategories?,includeGeometry?,includeLinked?,modelBounds?,limit?}.",
      "group": "Selection",
      "example": "export visible electrical devices with mapping",
      "risk": "low",
      "required_fields": [],
      "optional_fields": [
        "viewId",
        "imageSize",
        "includeMapping",
        "categories",
        "excludeCategories",
        "includeGeometry",
        "includeLinked",
        "modelBounds",
        "limit"
      ],
      "enums": {},
      "units": [
        {
          "unit": "pixels",
          "fields": [
            "imageSize",
            "items[*].anchor.image.x",
            "items[*].anchor.image.y",
            "items[*].bbox.image.minX",
            "items[*].bbox.image.minY",
            "items[*].bbox.image.maxX",
            "items[*].bbox.image.maxY"
          ]
        },
        {
          "unit": "feet",
          "fields": [
            "items[*].anchor.model.x",
            "items[*].anchor.model.y",
            "items[*].anchor.model.z",
            "items[*].bbox.model.min.x",
            "items[*].bbox.model.min.y",
            "items[*].bbox.model.min.z",
            "items[*].bbox.model.max.x",
            "items[*].bbox.model.max.y",
            "items[*].bbox.model.max.z",
            "items[*].geometry.lengthFt"
          ]
        }
      ],
      "notes": [
        "Use this when you need a full visible-element manifest tied to the same exported image and affine mapping basis.",
        "Supported for crop-box-backed 2D views only; use sheet-aware tools for DrawingSheet workflows.",
        "categories/excludeCategories accept BuiltInCategory tokens and exact category names when tokens are unavailable.",
        "includeLinked=true keeps link-scoped ids and transformed source/host/hostingSurface payloads so linked rows can be consumed without re-deriving host coordinates.",
        "Orientation payloads include facing/hand vectors plus plan-azimuth and basis vectors when available; linked rows are transformed into host coordinates.",
        "Mapping corners are emitted from the saved raster frame; crop-box corners are included only as reference metadata when the raster aspect differs."
      ],
      "request_schema": {
        "oneOf": [
          {
            "type": "null"
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "viewId": {
                "type": "integer"
              },
              "imageSize": {
                "type": "integer"
              },
              "includeMapping": {
                "type": "boolean"
              },
              "categories": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "maxItems": 100
              },
              "excludeCategories": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "maxItems": 100
              },
              "includeGeometry": {
                "type": "boolean"
              },
              "includeLinked": {
                "type": "boolean"
              },
              "modelBounds": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 6,
                "maxItems": 6
              },
              "limit": {
                "type": "integer",
                "minimum": 1,
                "maximum": 2000
              }
            },
            "required": []
          }
        ]
      },
      "response_schema": {
        "type": "object",
        "additionalProperties": true,
        "properties": {},
        "required": []
      },
      "examples": []
    }
  ]
